-- No siembra autoridades, personas o concesiones. Registro firmado e instrucciones nuevas; historia previa intacta.
CREATE TABLE authority_registry(id INT PRIMARY KEY CHECK(id=1),revision BIGINT NOT NULL);
INSERT INTO authority_registry VALUES(1,0);
CREATE TABLE authority_batch(revision BIGINT PRIMARY KEY,payload_sha256 CHAR(64) NOT NULL,key_id VARCHAR(64) NOT NULL,signed_payload TEXT NOT NULL,signature_text VARCHAR(128) NOT NULL,issued_ms BIGINT NOT NULL,expires_ms BIGINT NOT NULL,imported_ms BIGINT NOT NULL,CHECK(expires_ms>issued_ms));
CREATE TABLE authority_binding(batch_revision BIGINT NOT NULL,actor_id VARCHAR(64) NOT NULL,person_id VARCHAR(64) NOT NULL,valid_from BIGINT NOT NULL,valid_until BIGINT NOT NULL,PRIMARY KEY(batch_revision,actor_id),FOREIGN KEY(batch_revision) REFERENCES authority_batch(revision),FOREIGN KEY(actor_id) REFERENCES core_actor(id),CHECK(valid_until>valid_from));
CREATE TABLE authority_mandate(batch_revision BIGINT NOT NULL,id VARCHAR(64) NOT NULL,person_id VARCHAR(64) NOT NULL,function_code VARCHAR(80) NOT NULL,role_code VARCHAR(32) NOT NULL,scope_code VARCHAR(24) NOT NULL,unit_code VARCHAR(8),site_id VARCHAR(40),valid_from BIGINT NOT NULL,valid_until BIGINT NOT NULL,can_approve BOOLEAN NOT NULL,can_revoke BOOLEAN NOT NULL,basis_ref VARCHAR(180) NOT NULL,basis_sha256 CHAR(64) NOT NULL,PRIMARY KEY(batch_revision,id),FOREIGN KEY(batch_revision) REFERENCES authority_batch(revision),FOREIGN KEY(unit_code) REFERENCES core_unit(code),FOREIGN KEY(site_id) REFERENCES core_site(id),CHECK(valid_until>valid_from));
CREATE TABLE access_instruction(id VARCHAR(36) PRIMARY KEY,requester_id VARCHAR(64) NOT NULL,beneficiary_id VARCHAR(64) NOT NULL,role_code VARCHAR(32) NOT NULL,scope_code VARCHAR(24) NOT NULL,unit_code VARCHAR(8),site_id VARCHAR(40),valid_from BIGINT NOT NULL,valid_until BIGINT NOT NULL,reason_text VARCHAR(1000) NOT NULL,request_hash CHAR(64) NOT NULL,state VARCHAR(24) NOT NULL,revision BIGINT NOT NULL,created_ms BIGINT NOT NULL,approver_id VARCHAR(64),approver_person VARCHAR(64),beneficiary_person VARCHAR(64),authority_revision BIGINT,mandate_id VARCHAR(64),approved_ms BIGINT,decision_reason VARCHAR(1000),assignment_id VARCHAR(36) UNIQUE,executed_by VARCHAR(64),executed_ms BIGINT,revoked_by VARCHAR(64),revoked_ms BIGINT,revocation_reason VARCHAR(1000),FOREIGN KEY(requester_id) REFERENCES core_actor(id),FOREIGN KEY(beneficiary_id) REFERENCES core_actor(id),FOREIGN KEY(approver_id) REFERENCES core_actor(id),FOREIGN KEY(executed_by) REFERENCES core_actor(id),FOREIGN KEY(revoked_by) REFERENCES core_actor(id),FOREIGN KEY(authority_revision,mandate_id) REFERENCES authority_mandate(batch_revision,id),FOREIGN KEY(unit_code) REFERENCES core_unit(code),FOREIGN KEY(site_id) REFERENCES core_site(id),CHECK(valid_until>valid_from),CHECK(state IN ('PENDIENTE','APROBADA','RECHAZADA','EJECUTADA','REVOCADA')));
CREATE TABLE approved_assignment(assignment_id VARCHAR(36) PRIMARY KEY,instruction_id VARCHAR(36) NOT NULL UNIQUE,FOREIGN KEY(assignment_id) REFERENCES staff_assignment(id) ON DELETE CASCADE,FOREIGN KEY(instruction_id) REFERENCES access_instruction(id));
CREATE TABLE authority_event(seq BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id VARCHAR(64),resource_id VARCHAR(64),action_code VARCHAR(40) NOT NULL,result_code VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,snapshot_doc TEXT,FOREIGN KEY(actor_id) REFERENCES core_actor(id));
CREATE TABLE authority_command(id VARCHAR(36) PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,action_code VARCHAR(32) NOT NULL,request_hash CHAR(64) NOT NULL,result_id VARCHAR(36) NOT NULL,result_revision BIGINT NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(result_id) REFERENCES access_instruction(id));
CREATE INDEX ix_access_instruction_state ON access_instruction(state,valid_until);
